from contextlib import closing
from pathlib import Path
import argparse,collections,hashlib,importlib.util,json,sqlite3,subprocess,sys,tempfile,threading,time
ROOT=Path('/tmp/agenturm-terminal-result');sys.path.insert(0,str(ROOT))
parser=argparse.ArgumentParser();parser.add_argument('--worker',choices=['before','after']);parser.add_argument('--module',type=Path);parser.add_argument('--base',type=int);args=parser.parse_args()
if args.worker:
    import observatory
    if args.worker=='before':
        spec=importlib.util.spec_from_file_location('observatory.operation_facts',args.module)
        module=importlib.util.module_from_spec(spec);sys.modules[spec.name]=module;spec.loader.exec_module(module)
    else:
        import observatory.operation_facts as module
    local=threading.local();buckets=[];lock=threading.Lock()
    def bucket():
        if not hasattr(local,'counts'):
            local.counts=collections.Counter()
            with lock:buckets.append(local.counts)
        return local.counts
    original_facts=module.operation_facts;original_normalize=module.normalize_operation_result;original_supersedes=module.supersedes_operation
    def facts(row):
        values=bucket();values['facts_total']+=1;values['facts_in_normalize'if getattr(local,'normalizing',0)else 'facts_in_supersedes'if getattr(local,'superseding',0)else 'facts_other']+=1
        return original_facts(row)
    def normalize(row):
        values=bucket();values['normalize_total']+=1;values['normalize_qualified']+=row.get('detail_role')=='operation_v1';local.normalizing=getattr(local,'normalizing',0)+1
        try:return original_normalize(row)
        finally:local.normalizing-=1
    def supersedes(*rows):
        bucket()['supersedes_total']+=1;local.superseding=getattr(local,'superseding',0)+1
        try:return original_supersedes(*rows)
        finally:local.superseding-=1
    module.operation_facts=facts;module.normalize_operation_result=normalize;module.supersedes_operation=supersedes
    from observatory.core import Store
    from observatory.server import BoundedHTTPServer,handler_for
    from scripts.benchmark_http_tails import payload,http_attempt
    with tempfile.TemporaryDirectory(prefix='agenturm-terminal-http-')as directory:
        path=Path(directory)/'generated.db';store=Store(path,async_derived_refresh=True)
        deadline=time.monotonic()+5
        while not store.index_status()['ready']and time.monotonic()<deadline:time.sleep(.01)
        if not store.index_status()['ready']:raise RuntimeError('Tiny target fixture did not initialize')
        server=BoundedHTTPServer(('127.0.0.1',0),handler_for(store,'generated-token',quiet=True));serverthread=threading.Thread(target=server.serve_forever);serverthread.start()
        receiver=http_attempt(server.server_port,'/api/health','generated-token')[1]['receiver_id']
        writes=[];reads=[];start=time.monotonic_ns()+100_000_000
        def reader():
            endpoints=('/api/sessions?limit=500','/api/mcp?limit=100')
            for pair in range(6):
                time.sleep(max(0,(start+300_000_000+pair*1_000_000_000-time.monotonic_ns())/1e9))
                for endpoint in endpoints if pair%2==0 else endpoints[::-1]:
                    row,data=http_attempt(server.server_port,endpoint,'generated-token',receiver=receiver)
                    row.update(pair=pair,body_receiver=data.get('receiver_id')if isinstance(data,dict)else None);reads.append(row)
        thread=threading.Thread(target=reader);thread.start()
        try:
            for index in range(60):
                scheduled=start+index*100_000_000;time.sleep(max(0,(scheduled-time.monotonic_ns())/1e9))
                row,data=http_attempt(server.server_port,'/api/spans','generated-token',method='POST',receiver=receiver,
                    body=json.dumps(payload(index,args.base),sort_keys=True,separators=(',',':')).encode())
                row.update(sequence=index,lateness_ms=max(0,(row['started_ns']-scheduled)/1e6),accepted=data.get('accepted')if isinstance(data,dict)else None);writes.append(row)
            thread.join(10)
        finally:
            server.shutdown();server.server_close();serverthread.join(10);workers=[store._migration_thread,store._derived_thread];store.close()
        if thread.is_alive()or serverthread.is_alive()or any(w and w.is_alive()for w in workers):raise RuntimeError('Owned workers did not drain')
        counts=collections.Counter()
        for value in buckets:counts.update(value)
        with closing(sqlite3.connect(path))as db:raw={name:db.execute('SELECT COUNT(*) FROM '+name).fetchone()[0]for name in ('spans','trace_activity','agent_nodes')}
        print(json.dumps(dict(mode=args.worker,counts=dict(counts),raw_counts=raw,writes=writes,reads=reads,derived_error=store.last_derived_error,elapsed_s=(time.monotonic_ns()-start)/1e9)));sys.exit(0)
with tempfile.TemporaryDirectory(prefix='agenturm-terminal-source-')as directory:
    old=Path(directory)/'operation_facts.py';old.write_bytes(subprocess.check_output(['git','show','f477883:observatory/operation_facts.py'],cwd=ROOT))
    rows=[];base=time.time_ns()
    for mode in ('before','after','after','before'):
        value=json.loads(subprocess.check_output([sys.executable,__file__,'--worker',mode,'--module',str(old),'--base',str(base)],text=True));rows.append(value)
        print({key:value[key]for key in ('mode','counts','raw_counts','elapsed_s')},flush=True)
    result=dict(diagnostic_only=True,publishable=False,base_ns=base,design='Separate processes per module mode; tiny receiver/client shared process; per-thread call counters; all60writes finish/catchup, NOT registered deadline acceptance.',before_module_sha256=hashlib.sha256(old.read_bytes()).hexdigest(),after_module_sha256=hashlib.sha256((ROOT/'observatory/operation_facts.py').read_bytes()).hexdigest(),rows=rows)
    Path('/tmp/agenturm-terminal-http-target-results.json').write_text(json.dumps(result,indent=2))
